/**
 * App versions, compared the same way by the server, admin and the apps.
 * "1.2.10" is newer than "1.2.9"; missing parts count as 0; anything that is
 * not a version compares as 0.0.0, so a bad value never locks anyone out.
 */
const parts = (v) => String(v || '').split('.').map((n) => (Number.isFinite(Number(n)) ? Number(n) : 0));

/** Negative when a is older than b, 0 when equal, positive when newer. */
export function compareVersions(a, b) {
  const x = parts(a); const y = parts(b);
  for (let i = 0; i < Math.max(x.length, y.length, 3); i += 1) {
    const d = (x[i] || 0) - (y[i] || 0);
    if (d) return d;
  }
  return 0;
}

export const isOlder = (version, than) => compareVersions(version, than) < 0;

export const VERSION_RE = /^\d+(\.\d+){0,2}$/;

/** The three phone apps and their Play Store package, for the "Update" link. */
export const APP_PACKAGES = { customer: 'com.zappyone.app', servicepro: 'com.zappyone.servicepro', rakshak: 'com.zappyone.rakshak' };
